INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1, 'Master Ball', 'Pokeballs', 'The best Ball with the ultimate level of performance. It will catch any wild Pokémon without fail.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (2, 'Ultra Ball', 'Pokeballs', 'An ultra-performance Ball that provides a higher Pokémon catch rate than a Great Ball.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (3, 'Great Ball', 'Pokeballs', 'A good, high-performance Ball that provides a higher Pokémon catch rate than a standard Poké Ball.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (4, 'Poké Ball', 'Pokeballs', 'A device for catching wild Pokémon. It is thrown like a ball at the target. It is designed as a capsule system.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (5, 'Safari Ball', 'Pokeballs', 'A special Poké Ball that is used only in the Great Marsh. It is decorated in a camouflage pattern.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (6, 'Net Ball', 'Pokeballs', 'A somewhat different Poké Ball that works especially well on Water- and Bug-type Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (7, 'Dive Ball', 'Pokeballs', 'A somewhat different Poké Ball that works especially well on Pokémon that live underwater.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (8, 'Nest Ball', 'Pokeballs', 'A somewhat different Poké Ball that works especially well on weaker Pokémon in the wild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (9, 'Repeat Ball', 'Pokeballs', 'A somewhat different Poké Ball that works especially well on Pokémon species that were previously caught.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (10, 'Timer Ball', 'Pokeballs', 'A somewhat different BALL that becomes progressively better the more turns there are in a battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (11, 'Luxury Ball', 'Pokeballs', 'A comfortable Poké Ball that makes a caught wild Pokémon quickly grow friendly.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (12, 'Premier Ball', 'Pokeballs', 'A somewhat rare Poké Ball that has been specially made to commemorate an event of some sort.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (13, 'Dusk Ball', 'Pokeballs', 'A somewhat different Poké Ball that makes it easier to catch wild Pokémon at night or in dark places like caves.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (14, 'Heal Ball', 'Pokeballs', 'A remedial Poké Ball that restores the caught Pokémon''s HP and eliminates any status problem.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (15, 'Quick Ball', 'Pokeballs', 'A somewhat different Poké Ball that provides a better catch rate if it is used at the start of a wild encounter.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (16, 'Cherish Ball', 'Pokeballs', 'A quite rare Poké Ball that has been specially crafted to commemorate an occasion of some sort.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (17, 'Potion', 'Medicine', 'Restores 20 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (18, 'Antidote', 'Medicine', 'A spray-type medicine. It lifts the effect of poison from one Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (19, 'Burn Heal', 'Medicine', 'A spray-type medicine. It heals a single Pokémon that is suffering from a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (20, 'Ice Heal', 'Medicine', 'A spray-type medicine. It defrosts a Pokémon that has been frozen solid.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (21, 'Awakening', 'Medicine', 'A spray-type medicine. It awakens a Pokémon from the clutches of sleep.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (22, 'Paralyze Heal', 'Medicine', 'A spray-type medicine. It eliminates paralysis from a single Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (23, 'Full Restore', 'Medicine', 'A medicine that fully restores the HP and heals any status problems of a single Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (24, 'Max Potion', 'Medicine', 'Fully restores HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (25, 'Hyper Potion', 'Medicine', 'Restores 120 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (26, 'Super Potion', 'Medicine', 'Restores 60 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (27, 'Full Heal', 'Medicine', 'A spray-type medicine. It heals all the status problems of a single Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (28, 'Revive', 'Medicine', 'A medicine that revives a fainted Pokémon. It restores half the Pokémon''s maximum HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (29, 'Max Revive', 'Medicine', 'A medicine that revives a fainted Pokémon. It fully restores the Pokémon''s HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (30, 'Fresh Water', 'Medicine', 'Restores 30 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (31, 'Soda Pop', 'Medicine', 'Restores 50 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (32, 'Lemonade', 'Medicine', 'Restores 70 HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (33, 'Moomoo Milk', 'Medicine', 'Milk with a very high nutrition content. It restores the HP of one Pokémon by 100 points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (34, 'Energy Powder', 'Medicine', 'Restores 60 HP but lowers Friendship.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (35, 'Energy Root', 'Medicine', 'Restores 120 HP but lowers Friendship.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (36, 'Heal Powder', 'Medicine', 'Heals all status problems, but lowers Friendship.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (37, 'Revival Herb', 'Medicine', 'Revives a Pokémon to max HP, but lowers Friendship.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (38, 'Ether', 'Medicine', 'It restores the PP of a Pokémon''s selected move by a maximum of 10 points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (39, 'Max Ether', 'Medicine', 'It fully restores the PP of a single selected move that has been learned by the target Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (40, 'Elixir', 'Medicine', 'It restores the PP of all the moves learned by the targeted Pokémon by 10 points each.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (41, 'Max Elixir', 'Medicine', 'It fully restores the PP of all the moves learned by the targeted Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (42, 'Lava Cookie', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (43, 'Berry Juice', 'Medicine', 'A 100% pure juice made of Berries. It restores the HP of one Pokémon by just 20 points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (44, 'Sacred Ash', 'Medicine', 'It revives all fainted Pokémon. In doing so, it also fully restores their HP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (45, 'HP Up', 'Medicine', 'Increases HP EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (46, 'Protein', 'Medicine', 'Increases Attack EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (47, 'Iron', 'Medicine', 'Increases Defense EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (48, 'Carbos', 'Medicine', 'Increases Speed EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (49, 'Calcium', 'Medicine', 'Increases Special Attack EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (50, 'Rare Candy', 'Medicine', 'A candy that is packed with energy. It raises the level of a single Pokémon by one.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (51, 'PP Up', 'Medicine', 'It slightly raises the maximum PP of a selected move that has been learned by the target Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (52, 'Zinc', 'Medicine', 'Increases Special Defense EVs by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (53, 'PP Max', 'Medicine', 'It maximally raises the top PP of a selected move that has been learned by the target Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (54, 'Old Gateau', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (55, 'Guard Spec.', 'Battle items', 'Prevents stat reduction for five turns.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (56, 'Dire Hit', 'Battle items', 'Raises critical-hit ratio of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (57, 'X Attack', 'Battle items', 'Raises Attack of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (58, 'X Defense', 'Battle items', 'Raises Defense of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (59, 'X Speed', 'Battle items', 'Raises Speed of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (60, 'X Accuracy', 'Battle items', 'Raises Accuracy of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (61, 'X Sp. Atk', 'Battle items', 'Raises Special Attack of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (62, 'X Sp. Def', 'Battle items', 'Raises Special Defense of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (63, 'Poké Doll', 'General items', 'A doll that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (64, 'Fluffy Tail', 'General items', 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (65, 'Blue Flute', 'General items', 'A toy flute made from blue glass. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (66, 'Yellow Flute', 'General items', 'A toy flute made from yellow glass. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (67, 'Red Flute', 'General items', 'A toy flute made from red glass. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (68, 'Black Flute', 'General items', 'A toy flute made from black glass. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (69, 'White Flute', 'General items', 'A toy flute made from white glass. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (70, 'Shoal Salt', 'General items', 'Pure salt that can be discovered deep inside the Shoal Cave. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (71, 'Shoal Shell', 'General items', 'A pretty seashell that can be found deep inside the Shoal Cave. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (72, 'Red Shard', 'General items', 'A small red shard. It appears to be from some sort of implement made long ago.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (73, 'Blue Shard', 'General items', 'A small blue shard. It appears to be from some sort of implement made long ago.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (74, 'Yellow Shard', 'General items', 'A small yellow shard. It appears to be from some sort of implement made long ago.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (75, 'Green Shard', 'General items', 'A small green shard. It appears to be from some sort of implement made long ago.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (76, 'Super Repel', 'General items', 'An item that prevents weak wild Pokémon from appearing for 200 steps after its use.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (77, 'Max Repel', 'General items', 'An item that prevents weak wild Pokémon from appearing for 250 steps after its use.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (78, 'Escape Rope', 'General items', 'A long, durable rope. Use it to escape instantly from a cave or a dungeon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (79, 'Repel', 'General items', 'An item that prevents weak wild Pokémon from appearing for 100 steps after its use.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (80, 'Sun Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (81, 'Moon Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (82, 'Fire Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (83, 'Thunder Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (84, 'Water Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (85, 'Leaf Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (86, 'Tiny Mushroom', 'General items', 'A small and rare mushroom. It is sought after by collectors.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (87, 'Big Mushroom', 'General items', 'A large and rare mushroom. It is sought after by collectors.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (88, 'Pearl', 'General items', 'A somewhat-small pearl that sparkles in a pretty silver color. It can be sold cheaply to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (89, 'Big Pearl', 'General items', 'A quite-large pearl that sparkles in a pretty silver color. It can be sold at a high price to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (90, 'Stardust', 'General items', 'Lovely, red-colored sand with a loose, silky feel. It can be sold at a high price to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (91, 'Star Piece', 'General items', 'A shard of a pretty gem that sparkles in a red color. It can be sold at a high price to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (92, 'Nugget', 'General items', 'A nugget of pure gold that gives off a lustrous gleam. It can be sold at a high price to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (93, 'Heart Scale', 'General items', 'A pretty, heart-shaped scale that is extremely rare. It glows faintly in the colors of the rainbow.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (94, 'Honey', 'General items', 'A sweet honey with a lush aroma that attracts wild Pokémon when it is used in grass, caves, or on special trees.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (95, 'Growth Mulch', 'General items', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (96, 'Damp Mulch', 'General items', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (97, 'Stable Mulch', 'General items', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (98, 'Gooey Mulch', 'General items', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (99, 'Root Fossil', 'General items', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a plant root.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (100, 'Claw Fossil', 'General items', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a claw.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (102, 'Dome Fossil', 'General items', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a shell.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (103, 'Old Amber', 'General items', 'A piece of amber that contains the genetic material of an ancient Pokémon. It is clear with a reddish tint.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (104, 'Armor Fossil', 'General items', 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a collar.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (105, 'Skull Fossil', 'General items', 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a head.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (106, 'Rare Bone', 'General items', 'A bone that is extremely valuable for Pokémon archeology. It can be sold for a high price to shops.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (107, 'Shiny Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (108, 'Dusk Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (109, 'Dawn Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (110, 'Oval Stone', 'General items', 'Evolves Happiny when held.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (111, 'Odd Keystone', 'General items', 'A vital item that is needed to keep a stone tower from collapsing. Voices can be heard from it occasionally.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (112, 'Griseous Orb', 'Hold items', 'Increases the power of Dragon- and Ghost-type moves when held by Giratina, and changes it to Origin Forme.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (113, 'Tea', 'Key Items', 'An aromatic tea prepared by an old lady. It will slake even the worst thirst.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (115, 'Autograph', 'Key Items', 'The autograph you got from the Vermilion City Gym Leader, Lt. Surge. He wrote, "Good luck!"');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (116, 'Douse Drive', 'Hold items', 'Changes Techno Blast to a Water-type move when held by Genesect.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (117, 'Shock Drive', 'Hold items', 'Changes Techno Blast to an Electric-type move when held by Genesect.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (118, 'Burn Drive', 'Hold items', 'Changes Techno Blast to a Fire-type move when held by Genesect.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (119, 'Chill Drive', 'Hold items', 'Changes Techno Blast to an Ice-type move when held by Genesect.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (123, 'TM Case', 'Key Items', 'A case that holds TMs and HMs. It is attached to the BAG''s compartment for important items.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (134, 'Sweet Heart', 'Medicine', 'Very sweet chocolate. It restores the HP of one Pokémon by only 20 points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (135, 'Adamant Orb', 'Hold items', 'Increases the power of Dragon- and Steel-type moves when held by Dialga.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (136, 'Lustrous Orb', 'Hold items', 'Increases the power of Dragon- and Water-type moves when held by Palkia.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (149, 'Cheri Berry', 'Berries', 'If held by a Pokémon, it recovers from paralysis.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (150, 'Chesto Berry', 'Berries', 'If held by a Pokémon, it recovers from sleep.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (151, 'Pecha Berry', 'Berries', 'If held by a Pokémon, it recovers from poison.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (152, 'Rawst Berry', 'Berries', 'If held by a Pokémon, it recovers from a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (153, 'Aspear Berry', 'Berries', 'If held by a Pokémon, it defrosts it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (154, 'Leppa Berry', 'Berries', 'If held by a Pokémon, it restores a move''s PP by 10.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (155, 'Oran Berry', 'Berries', 'If held by a Pokémon, it heals the user by just 10 HP.');
