INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (157, 'Lum Berry', 'Berries', 'If held by a Pokémon, it recovers from any status problem.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (158, 'Sitrus Berry', 'Berries', 'If held by a Pokémon, it heals the user''s HP a little.');
