INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (430, 'Rule Book', 'Key Items', 'It lists the rules for holding battles. For linked battles, you may choose which set of rules you wish to use.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (431, 'Poké Radar', 'Key Items', 'A tool that can search out Pokémon that are hiding in grass. Its battery is recharged as you walk.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (432, 'Point Card', 'Key Items', 'A card that lists the Battle Points you have earned. ');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (433, 'Journal', 'Key Items', 'A notebook that keeps a day-to-day record of your adventure so far. ');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (434, 'Seal Case', 'Key Items', 'A case for storing Seals that can be applied to the capsule cases of Poké Balls.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (435, 'Fashion Case', 'Key Items', 'A lovely case to store colorful Props for your Pokémon to wear in a musical.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (436, 'Seal Bag', 'Key Items', 'A tiny bag that can hold ten Seals for decorating Poké Balls.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (437, 'Pal Pad', 'Key Items', 'A convenient notepad that is used for registering your friends, Friend Codes, and keeping a record of game play.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (438, 'Works Key', 'Key Items', 'A large key for operating the doors of the Valley Windworks in the canyon. It was held by a Team Galactic Grunt.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (439, 'Old Charm', 'Key Items', 'An ancient good-luck charm made of Pokémon bones to be taken to the elder of Celestic Town.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (440, 'Galactic Key', 'Key Items', 'A card key for disengaging security systems in the Galactic HQ. Losing it can result in punishment, apparently.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (441, 'Red Chain', 'Key Items', 'A mythical chain that is said to link the legendary Pokémon that created the Sinnoh region.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (442, 'Town Map', 'Key Items', 'A very convenient map that can be viewed anytime. It even shows your present location.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (443, 'Vs. Seeker', 'Key Items', 'A device that indicates Trainers who want to battle. Its battery charges while you walk.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (444, 'Coin Case', 'Key Items', 'A case for holding Coins obtained at the Game Corner. It holds up to 50,000 Coins.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (445, 'Old Rod', 'Key Items', 'An old and beat-up fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (446, 'Good Rod', 'Key Items', 'A new, good-quality fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (447, 'Super Rod', 'Key Items', 'An awesome, high-tech fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (448, 'Sprayduck', 'Key Items', 'A watering can shaped like a PSYDUCK. It helps promote healthy growth of Berries planted in soft soil.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (449, 'Poffin Case', 'Key Items', 'A case for storing Poffin cooked from Berries. ');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (451, 'Suite Key', 'Key Items', 'A key to one of the suites at the luxury hotel by a lake. For some odd reason, it often disappears.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (452, 'Oak''s Letter', 'Key Items', 'A letter from Prof. Oak. Written in it is a request for you to go to Rt. 224.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (453, 'Lunar Wing', 'Key Items', 'A feather that glows like the moon. It is said to possess the power to dispel nightmares.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (454, 'Member Card', 'Key Items', 'A card needed for entering the inn in Canalave City. Oddly, the last date marked on it was 50 years ago.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (455, 'Azure Flute', 'Key Items', 'A flute that puts out echoing sounds that do not seem to be of this world. It is unknown who made it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (457, 'Contest Pass', 'Key Items', 'The pass required for entering POKéMON CONTESTS. It has a drawing of an award ribbon on it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (458, 'Magma Stone', 'Key Items', 'A stone formed when boulders melted in intensely hot magma, then hardened. Magma remains sealed inside.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (460, 'Coupon 1', 'Key Items', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (461, 'Coupon 2', 'Key Items', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (462, 'Coupon 3', 'Key Items', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (464, 'Secret Potion', 'Key Items', 'A fantastic medicine dispensed by the pharmacy in Cianwood City. It fully heals a Pokémon of any ailment.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (465, 'Vs. Recorder', 'Key Items', 'An amazing device that can record a battle either between friends or at a special battle facility.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (466, 'Gracidea', 'Key Items', 'A flower sometimes bundled in bouquets to convey gratitude on special occasions like birthdays.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (468, 'Apricorn Box', 'Key Items', 'A handy box where you can store up to 99 Apricorns of each kind.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (469, 'Unown Report', 'Key Items', 'A report of all the discovered kinds of UNOWN.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (470, 'Berry Pots', 'Key Items', 'Handy containers for cultivating Berries wherever you go.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (471, 'Dowsing Machine', 'Key Items', 'Searches for hidden items on the ground.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (472, 'Blue Card', 'Key Items', 'A card to save points for the Buena''s Password show.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (473, 'Slowpoke Tail', 'Key Items', 'A very tasty tail of something. It sells for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (474, 'Clear Bell', 'Key Items', 'A very old-fashioned bell that makes a gentle ringing.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (477, 'Squirt Bottle', 'Key Items', 'A bottle used for watering plants in the Berry Pots.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (478, 'Red Scale', 'Key Items', 'A scale from the red GYARADOS. It glows red like a flame.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (479, 'Lost Item', 'Key Items', 'The Mime Jr. doll that was lost by the Copycat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (480, 'Pass', 'Key Items', 'A ticket required for riding the Magnet Train. It allows you to ride whenever and however much you''d like.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (481, 'Machine Part', 'Key Items', 'An important machine part for the Power Plant that was stolen.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (482, 'Silver Wing', 'Key Items', 'A strange, silvery feather that sparkles.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (483, 'Rainbow Wing', 'Key Items', 'A mystical rainbow feather that sparkles.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (484, 'Mystery Egg', 'Key Items', 'A mysterious Egg obtained from Mr. Pokémon. What''s in the Egg is unknown.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (485, 'Red Apricorn', 'General items', 'A red Apricorn. It assails your nostrils.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (486, 'Blue Apricorn', 'General items', 'A blue Apricorn. It smells a bit like grass.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (487, 'Yellow Apricorn', 'General items', 'A yellow Apricorn. It has an invigorating scent.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (488, 'Green Apricorn', 'General items', 'A green Apricorn. It has a mysterious, aromatic scent.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (489, 'Pink Apricorn', 'General items', 'A pink Apricorn. It has a nice, sweet scent.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (490, 'White Apricorn', 'General items', 'A white Apricorn. It doesn''t smell like anything.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (491, 'Black Apricorn', 'General items', 'A black Apricorn It has an indescribable scent.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (492, 'Fast Ball', 'Pokeballs', 'A Poké Ball that makes it easier to catch Pokémon which are quick to run away.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (493, 'Level Ball', 'Pokeballs', 'A Poké Ball for catching Pokémon that are a lower level than your own.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (494, 'Lure Ball', 'Pokeballs', 'A Poké Ball for catching Pokémon hooked by a Rod when fishing.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (495, 'Heavy Ball', 'Pokeballs', 'A Poké Ball for catching very heavy Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (496, 'Love Ball', 'Pokeballs', 'Poké Ball for catching Pokémon that are the opposite gender of your Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (497, 'Friend Ball', 'Pokeballs', 'A Poké Ball that makes caught Pokémon more friendly.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (498, 'Moon Ball', 'Pokeballs', 'A Poké Ball for catching Pokémon that evolve using the Moon Stone.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (499, 'Sport Ball', 'Pokeballs', 'A special Poké Ball for the Bug-Catching Contest.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (500, 'Park Ball', 'Pokeballs', 'A special Poké Ball for the Pal Park.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (501, 'Photo Album', 'Key Items', 'A nice photo album for storing all the photos taken along your adventure.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (502, 'GB Sounds', 'Key Items', 'A music player that allows you to listen to nostalgic songs. It''s operated with a single switch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (503, 'Tidal Bell', 'Key Items', 'A very old-fashioned bell that makes a gentle ringing.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (504, 'Rage Candy Bar', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (505, 'Data Card 01', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many victories you''ve had.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (506, 'Data Card 02', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many losses you''ve had.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (507, 'Data Card 03', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon have dashed.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (508, 'Data Card 04', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon have jumped.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (509, 'Data Card 05', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won the Hurdle Dash.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (510, 'Data Card 06', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won the Relay Run.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (511, 'Data Card 07', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Pennant Capture.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (512, 'Data Card 08', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Block Smash.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (513, 'Data Card 09', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Disc Catch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (514, 'Data Card 10', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Snow Throw.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (515, 'Data Card 11', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many points your Pokémon scored.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (516, 'Data Card 12', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon have failed.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (517, 'Data Card 13', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon impeded themselves.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (518, 'Data Card 14', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon have tackled.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (519, 'Data Card 15', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon have fallen down.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (520, 'Data Card 16', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Ring Drop.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (521, 'Data Card 17', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Lamp Jump.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (522, 'Data Card 18', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Circle Push.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (523, 'Data Card 19', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many Link Pokéathlon wins you''ve had.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (524, 'Data Card 20', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many Link Pokéathlon losses you''ve had.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (525, 'Data Card 21', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won an event.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (526, 'Data Card 22', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve lost an event.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (527, 'Data Card 23', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve switched Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (528, 'Data Card 24', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve won Goal Roll.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (529, 'Data Card 25', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times your Pokémon won individual prizes.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (530, 'Data Card 26', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how many times you''ve instructed your Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (531, 'Data Card 27', 'Key Items', 'It holds Pokéathlon records. It''s a card that shows how much time you''ve spent in the Pokéathlon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (532, 'Jade Orb', 'Key Items', ' A shiny green orb that is said to have a legend and has a deep connection with the Hoenn region.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (533, 'Lock Capsule', 'Key Items', 'A sturdy Capsule that can only be opened with a special key.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (534, 'Red Orb', 'Key Items', 'A shiny red orb that is said to have a legend and has a deep connection with the Hoenn region.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (535, 'Blue Orb', 'Key Items', 'A shiny blue orb that is said to have a legend and has a deep connection with the Hoenn region.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (536, 'Enigma Stone', 'Key Items', 'A crystal ball that was excavated from the ground. A very beautiful stone that is covered with bits of rock and earth.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (538, 'Eviolite', 'Hold items', 'A mysterious evolutionary lump. When held, it raises the Defense and Sp. Def of a Pokémon that can still evolve.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (539, 'Float Stone', 'Hold items', 'A very light stone. It reduces the weight of a Pokémon when held.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (540, 'Rocky Helmet', 'Hold items', 'If the holder of this item takes damage, the attacker will also be damaged upon contact.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (541, 'Air Balloon', 'Hold items', 'When held by a Pokémon, the Pokémon will float into the air. When the holder is attacked, this item will burst.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (542, 'Red Card', 'Hold items', 'A card with a mysterious power. When the holder is struck by a foe, the attacker is removed from battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (543, 'Ring Target', 'Hold items', 'Moves that would otherwise have no effect will land on the Pokémon that holds it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (544, 'Binding Band', 'Hold items', 'A band that increases the power of binding moves when held.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (545, 'Absorb Bulb', 'Hold items', 'A consumable bulb. If the holder is hit by a Water-type move, its Sp. Atk will rise.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (546, 'Cell Battery', 'Hold items', 'A consumable battery. If the holder is hit by an Electric-type move, its Attack will rise.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (547, 'Eject Button', 'Hold items', 'If the holder is hit by an attack, it will switch with another Pokémon in your party.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (548, 'Fire Gem', 'Hold items', 'Increases the power of a Fire-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (549, 'Water Gem', 'Hold items', 'Increases the power of a Water-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (550, 'Electric Gem', 'Hold items', 'Increases the power of an Electric-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (551, 'Grass Gem', 'Hold items', 'Increases the power of a Grass-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (552, 'Ice Gem', 'Hold items', 'Increases the power of an Ice-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (553, 'Fighting Gem', 'Hold items', 'Increases the power of a Fighting-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (554, 'Poison Gem', 'Hold items', 'Increases the power of a Poison-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (555, 'Ground Gem', 'Hold items', 'Increases the power of a Ground-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (556, 'Flying Gem', 'Hold items', 'Increases the power of a Flying-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (557, 'Psychic Gem', 'Hold items', 'Increases the power of a Psychic-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (559, 'Rock Gem', 'Hold items', 'Increases the power of a Rock-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (560, 'Ghost Gem', 'Hold items', 'Increases the power of a Ghost-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (561, 'Dragon Gem', 'Hold items', 'Increases the power of a Dragon-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (562, 'Dark Gem', 'Hold items', 'Increases the power of a Dark-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (563, 'Steel Gem', 'Hold items', 'Increases the power of a Steel-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (564, 'Normal Gem', 'Hold items', 'Increases the power of a Normal-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (572, 'Cover Fossil', 'General items', 'A fossil of an ancient Pokémon that lived in the sea in ancient times. It appears to be part of its back.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (573, 'Plume Fossil', 'General items', 'A fossil of an ancient Pokémon that flew in the sky in ancient times. It appears to be part of its wing.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (574, 'Liberty Pass', 'Key Items', 'A special pass to go to Liberty Garden. Board the ship in Castelia City.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (575, 'Pass Orb', 'Hold items', 'A mysterious orb containing the power of the Unova region, to be used when generating Pass Power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (576, 'Dream Ball', 'Pokeballs', 'A special Poké Ball that appears out of nowhere in a bag at the Entree Forest. It can catch any Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (577, 'Poké Toy', 'General items', 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (578, 'Prop Case', 'Key Items', 'A lovely case to store colorful Props for your Pokémon to wear in a musical.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (579, 'Dragon Skull', 'Key Items', 'A skull of a Pokémon which was said to have braved the angry waters to fly around the world.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (580, 'Balm Mushroom', 'General items', 'A rare mushroom which gives off a nice fragrance. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (581, 'Big Nugget', 'General items', 'A big nugget of pure gold that gives off a lustrous gleam. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (582, 'Pearl String', 'General items', 'Very large pearls that sparkle in a pretty silver color. A maniac will buy them for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (583, 'Comet Shard', 'General items', 'A shard which fell to the ground when a comet approached. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (584, 'Relic Copper', 'General items', 'A copper coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (585, 'Relic Silver', 'General items', 'A silver coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (586, 'Relic Gold', 'General items', 'A gold coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (587, 'Relic Vase', 'General items', 'A vase made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (588, 'Relic Band', 'General items', 'A bracelet made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (589, 'Relic Statue', 'General items', 'A stone figure made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (590, 'Relic Crown', 'General items', 'A crown made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (591, 'Casteliacone', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (592, 'Dire Hit 2', 'Battle items', 'Raises a Pokémon''s critical-hit ratio in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (593, 'X Speed 2', 'Battle items', 'Sharply raises Speed of a Pokémon in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (594, 'X Sp. Atk 2', 'Battle items', 'Sharply raises Special Attack of a Pokémon in battle.');
