INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (598, 'X Accuracy 2', 'Battle items', 'Sharply raises Accuracy of a Pokémon in battle.');
