INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (607, 'X Sp. Def 6', 'Battle items', 'Immensely raises Special Defense of a Pokémon in battle.');
