INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (611, 'Ability Urge', 'Battle items', 'When used, it activates the Ability of an ally Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (612, 'Item Drop', 'Battle items', 'When used, it causes an ally Pokémon to drop a held item.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (613, 'Item Urge', 'Battle items', 'When used, it causes an ally Pokémon to use its held item.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (614, 'Reset Urge', 'Battle items', 'When used, it restores any stat changes of an ally Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (615, 'Dire Hit 3', 'Battle items', 'Greatly raises a Pokémon''s critical-hit ratio in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (616, 'Light Stone', 'Key Items', 'Reshiram''s body was destroyed and changed into this stone. It is said to be waiting for the emergence of a hero.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (617, 'Dark Stone', 'Key Items', 'Zekrom''s body was destroyed and changed into this stone. It is said to be waiting for the emergence of a hero.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (618, 'TM93', 'Machines', 'Teaches the move Wild Charge.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (619, 'TM94', 'Machines', 'Teaches the move Rock Smash/Surf.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (620, 'TM95', 'Machines', 'Teaches the move Snarl.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (623, 'Gram 1', 'Key Items', 'An important letter which Wingull delivers.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (624, 'Gram 2', 'Key Items', 'An important letter which Wingull delivers.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (625, 'Gram 3', 'Key Items', 'An important letter which Wingull delivers.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (626, 'Xtransceiver', 'Key Items', 'A high-tech transceiver with a camera function. It allows up to four-way calls.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (627, 'Medal Box', 'Key Items', 'A box-shaped machine that stores Medals and Medal information.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (629, 'DNA Splicers', 'General items', 'A splicer that fuses Kyurem and a certain Pokémon. They are said to have been one in the beginning.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (630, 'Permit', 'General items', 'A permit that is needed to enter the Nature Preserve. Not many know about it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (631, 'Oval Charm', 'General items', 'An oval charm said to increase the chance of Pokémon Eggs being found at the Day Care.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (632, 'Shiny Charm', 'General items', 'A shiny charm said to increase the chance of finding a Shiny Pokémon in the wild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (633, 'Plasma Card', 'Hold items', 'A card key needed to enter the password inside the Plasma Frigate.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (634, 'Grubby Hanky', 'Hold items', 'A handkerchief dropped by a regular at Café Warehouse. It smells faintly like a Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (635, 'Colress Machine', 'Hold items', 'A special device that wrings out the potential of Pokémon. It is an imperfect prototype.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (637, 'Dropped Item', 'Hold items', 'The Xtransceiver found at the Nimbasa City amusement park. It seems it belongs to a boy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (638, 'Reveal Glass', 'General items', 'A looking glass that reveals the truth. It''s a mysterious glass that returns a Pokémon to its original shape.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (639, 'Weakness Policy', 'Hold items', 'Sharply raises Attack and Special Attack if hit by a super-effective move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (640, 'Assault Vest', 'Hold items', 'Raises Special Defense but prevents the use of status moves.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (642, 'Prof''s Letter', 'Hold items', 'A letter that Professor Sycamore wrote to your mother. A faint but pleasant perfume seems to cling to the paper.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (643, 'Roller Skates', 'General items', 'Attaches roller skates to the bottom of your shoes, allowing you to glide quickly around and perform tricks.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (644, 'Pixie Plate', 'Hold items', 'Increases power of Fairy-type moves. Changes Arceus'' type to Fairy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (645, 'Ability Capsule', 'Hold items', 'A capsule that allows a Pokémon with two Abilities to switch between these Abilities when it is used.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (646, 'Whipped Dream', 'General items', 'Evolves Swirlix when traded holding the item.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (647, 'Sachet', 'General items', 'Evolves Spritzee when traded holding the item.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (648, 'Luminous Moss', 'Hold items', 'Raises Special Defense if hit by a Water-type move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (649, 'Snowball', 'Hold items', 'Raises Attack if hit by an Ice-type move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (650, 'Safety Goggles', 'Hold items', 'Prevents damage from weather and powder.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (651, 'Poké Flute', 'Key Items', 'A flute that is said to instantly awaken any POKéMON. It has a lovely tone.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (652, 'Rich Mulch', 'Key Items', 'Mulch to be used in a Berry field. It increases the Berry harvest without the need for particularly diligent care.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (653, 'Surprise Mulch', 'Key Items', 'Mulch to be used in a Berry field. It causes strange, sudden mutations based on the combination of Berries.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (654, 'Boost Mulch', 'Key Items', 'Mulch to be used in a Berry field. It increases the Berry harvest that can be grown by diligent watering.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (655, 'Amaze Mulch', 'Key Items', 'Mulch to be used in a Berry field. An amazing Mulch with the effects of Rich, Surprise, and Boost Mulch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (656, 'Gengarite', 'Hold items', 'Enables Gengar to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (657, 'Gardevoirite', 'Hold items', 'Enables Gardevoir to Mega Evolve during battle.');
