INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (686, 'Roseli Berry', 'Berries', 'If held by a Pokémon, this Berry will lessen the damage taken from one supereffective Fairy-type attack.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (687, 'Kee Berry', 'Berries', 'If held by a Pokémon, this Berry will increase the holder''s Defense if it''s hit with a physical move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (688, 'Maranga Berry', 'Berries', 'If held by a Pokémon, this Berry will increase the holder''s Sp. Def if it''s hit with a special move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (689, 'Sprinklotad', 'General items', 'A watering can shaped like a Lotad. It helps promote the healthy growth of any Berries planted in good, soft soil.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (690, 'TM96', 'Machines', 'Teaches the move Nature Power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (691, 'TM97', 'Machines', 'Teaches the move Dark Pulse.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (692, 'TM98', 'Machines', 'Teaches the move Power-Up Punch/Waterfall.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (693, 'TM99', 'Machines', 'Teaches the move Dazzling Gleam.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (694, 'TM100', 'Machines', 'Teaches the move Confide.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (695, 'Power Plant Pass', 'Hold items', 'This pass serves as an ID card for gaining access to the power plant that lies along Route 13.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (696, 'Mega Ring', 'Key Items', 'Enables Pokémon carrying Mega Stones to Mega Evolve in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (697, 'Intriguing Stone', 'Hold items', 'A rather curious stone that might appear to be valuable to some. It''s all in the eye of the beholder.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (699, 'Discount Coupon', 'General items', 'This special coupon allows you to buy items at a discount when you are shopping at a boutique.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (700, 'Elevator Key', 'Hold items', 'A card key that activates the elevator in Lysandre Labs. It is emblazoned with Team Flare''s logo.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (701, 'TMV Pass', 'General items', 'A commuter pass that allows the holder to ride the TMV between Lumiose City and Kiloude City at any time.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (704, 'Strange Souvenir', 'General items', 'An ornament depicting a Pokémon that is venerated as a protector in some region far from Kalos.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (705, 'Lens Case', 'Key Items', 'A rather chic-looking case for carrying contact lenses.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (706, 'Makeup Bag', 'Key Items', 'A rather chic-looking case for carrying lipsticks.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (708, 'Lumiose Galette', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (709, 'Shalour Sable', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (712, 'Looker Ticket', 'Hold items', 'A ticket that was handmade by Looker. It''s decorated with a liberal amount of glittery paint.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (713, 'Bike', 'Key Items', 'A folding Bike that enables a rider to get around much faster than with Running Shoes.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (714, 'Holo Caster', 'Key Items', 'A device that allows users to receive and view hologram clips at any time. It is also used to chat with others.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (715, 'Fairy Gem', 'General items', 'Increases the power of a Fairy-type move only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (718, 'Mach Bike', 'Key Items', 'A folding bicycle that is at least twice as fast as walking.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (719, 'Acro Bike', 'Key Items', 'A folding bicycle that is capable of stunts like jumps and wheelies.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (720, 'Wailmer Pail', 'Key Items', 'A nifty watering pail. Use it to promote strong growth in BERRIES planted in soft soil.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (721, 'Devon Parts', 'Key Items', 'A case that contains mechanical parts of some sort made by the Devon Corporation.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (722, 'Soot Sack', 'Key Items', 'A sack used to collect volcanic ash automatically during walks over deep ash.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (723, 'Basement Key', 'Key Items', 'A key that opens a door in the Goldenrod Tunnel.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (724, 'Pokéblock Kit', 'Key Items', 'A set containing a Berry Blender for making Pokéblocks and a Pokéblock Case for storing Pokéblocks.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (725, 'Letter', 'Key Items', 'An extremely important letter to STEVEN from the PRESIDENT of the DEVON CORPORATION.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (726, 'Eon Ticket', 'Key Items', 'The ticket required for sailing on a ferry to a distant southern island. It features a drawing of an island.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (727, 'Scanner', 'Key Items', 'A device used to search for life-forms in water. It looks too difficult to use.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (728, 'Go-Goggles', 'Key Items', 'A pair of protective goggles. They enable a TRAINER to travel through even desert sandstorms.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (730, 'Key to Room 1', 'Key Items', 'Unlocks Room 1 in Abandoned Ship/Sea Mauville.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (731, 'Key to Room 2', 'Key Items', 'Unlocks Room 2 in Abandoned Ship/Sea Mauville.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (732, 'Key to Room 4', 'Key Items', 'Unlocks Room 4 in Abandoned Ship/Sea Mauville.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (733, 'Key to Room 6', 'Key Items', 'Unlocks Room 6 in Abandoned Ship/Sea Mauville.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (734, 'Storage Key', 'Key Items', 'The key to Team Galactic''s sinister warehouse located at the edge of Veilstone City.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (735, 'Devon Scope', 'Key Items', 'A scope that signals the presence of any unseeable POKéMON. It is made by the DEVON CORP.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (737, 'HM07', 'Machines', 'Teaches the move Waterfall.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (738, 'Devon Scuba Gear', 'Key Items', 'A device made by Devon Corporation that provides oxygen to users during the use of Dive.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (740, 'Contest Costume', 'Key Items', 'A very cool suit to be worn during the Contest Spectacular.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (741, 'Magma Suit', 'Key Items', 'A suit made with the collective technological know-how of Team Magma. It can withstand any impact.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (742, 'Aqua Suit', 'Key Items', 'A suit made with the collective technological know-how of Team Aqua. It can withstand any impact.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (743, 'Pair of Tickets', 'Key Items', 'Tickets for two to the astronomical show being held at the Mossdeep Space Center.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (744, 'Mega Bracelet', 'Key Items', 'This cuff contains an untold power that somehow enables Pokémon carrying a Mega Stone to Mega Evolve in battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (752, 'Swampertite', 'Hold items', 'Enables Swampert to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (753, 'Sceptilite', 'Hold items', 'Enables Sceptile to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (754, 'Sablenite', 'Hold items', 'Enables Sableye to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (755, 'Altarianite', 'Hold items', 'Enables Altaria to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (756, 'Galladite', 'Hold items', 'Enables Gallade to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (757, 'Audinite', 'Hold items', 'Enables Audino to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (758, 'Metagrossite', 'Hold items', 'Enables Metagross to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (759, 'Sharpedonite', 'Hold items', 'Enables Sharpedo to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (760, 'Slowbronite', 'Hold items', 'Enables Slowbro to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (761, 'Steelixite', 'Hold items', 'Enables Steelix to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (762, 'Pidgeotite', 'Hold items', 'Enables Pidgeot to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (763, 'Glalitite', 'Hold items', 'Enables Glalie to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (764, 'Diancite', 'Hold items', 'Enables Diancie to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (765, 'Prison Bottle', 'Hold items', 'Transforms Hoopa Confined to Hoopa Unbound.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (767, 'Cameruptite', 'Hold items', 'Enables Camerupt to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (768, 'Lopunnite', 'Hold items', 'Enables Lopunny to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (769, 'Salamencite', 'Hold items', 'Enables Salamence to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (770, 'Beedrillite', 'Hold items', 'Enables Beedrill to Mega Evolve during battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (772, 'Meteorite', 'Key Items', 'A meteorite that fell from space onto MT. MOON long ago. It is very lumpy and hard.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (773, 'Key Stone', 'Key Items', 'A stone filled with an unexplained power. It makes Pokémon that battle with a Mega Stone Mega Evolve.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (774, 'Meteorite Shard', 'Key Items', 'One of the fragments of a Meteorite from Granite Cave. It''s faintly warm to the touch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (775, 'Eon Flute', 'Key Items', 'A flute that can be used to summon Latios or Latias no matter where you are.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (795, 'Bottle Cap', 'General items', 'Maximizes one IV stat in Hyper Training.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (796, 'Gold Bottle Cap', 'General items', 'Maximizes all of a Pokémon''s IV stats in Hyper Training.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (797, 'Z-Ring', 'Key Items', 'A mysterious ring that enables Pokémon to use Z-Power. It requires both the willpower and the physical power of the Trainer wearing it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (807, 'Normalium Z', 'Hold items', 'Allows the use of Breakneck Blitz, the Normal type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (808, 'Firium Z', 'Hold items', 'Allows the use of Inferno Overdrive, the Fire type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (809, 'Waterium Z', 'Hold items', 'Allows the use of Hydro Vortex, the Water type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (810, 'Electrium Z', 'Hold items', 'Allows the use of Gigavolt Havoc, the Electric type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (811, 'Grassium Z', 'Hold items', 'Allows the use of Bloom Doom, the Grass type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (812, 'Icium Z', 'Hold items', 'Allows the use of Subzero Slammer, the Ice type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (813, 'Fightinium Z', 'Hold items', 'Allows the use of All-Out Pummeling, the Fighting type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (814, 'Poisonium Z', 'Hold items', 'Allows the use of Acid Downpour, the Poison type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (815, 'Groundium Z', 'Hold items', 'Allows the use of Tectonic Rage, the Ground type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (816, 'Flyinium Z', 'Hold items', 'Allows the use of Supersonic Skystrike, the Flying type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (817, 'Psychium Z', 'Hold items', 'Allows the use of Shattered Psyche, the Psychic type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (818, 'Buginium Z', 'Hold items', 'Allows the use of Savage Spin-Out, the Bug type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (819, 'Rockium Z', 'Hold items', 'Allows the use of Continental Crush, the Rock type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (820, 'Ghostium Z', 'Hold items', 'Allows the use of Never-Ending Nightmare, the Ghost type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (821, 'Dragonium Z', 'Hold items', 'Allows the use of Devastating Drake, the Dragon type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (822, 'Darkinium Z', 'Hold items', 'Allows the use of Black Hole Eclipse, the Dark type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (823, 'Steelium Z', 'Hold items', 'Allows the use of Corkscrew Crash, the Steel type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (824, 'Fairium Z', 'Hold items', 'Allows the use of Twinkle Tackle, the Fairy type Z-Move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (825, 'Pikanium Z', 'Hold items', 'Allows Pikachu to upgrade Volt Tackle to a Z-Move, Catastropika.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (826, 'Decidium Z', 'Hold items', 'Allows Decidueye to upgrade Spirit Shackle to a Z-Move, Sinister Arrow Raid.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (827, 'Incinium Z', 'Hold items', 'Allows Incineroar to upgrade Darkest Lariat to a Z-Move, Malicious Moonsault.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (828, 'Primarium Z', 'Hold items', 'Allows Primarina to upgrade Sparkling Aria to a Z-Move, Oceanic Operetta.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (829, 'Tapunium Z', 'Hold items', 'Allows the Tapus to upgrade Nature''s Madness to a Z-Move, Guardian of Alola.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (830, 'Marshadium Z', 'Hold items', 'Allows Marshadow to upgrade Spectral Thief to a Z-Move, Soul-Stealing 7-Star Strike.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (831, 'Aloraichium Z', 'Hold items', 'Allows Alolan Raichu to upgrade Thunderbolt to a Z-Move, Stoked Sparksurfer.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (832, 'Snorlium Z', 'Hold items', 'Allows Snorlax to upgrade Giga Impact to a Z-Move, Pulverizing Pancake.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (833, 'Eevium Z', 'Hold items', 'Allows Eevee to upgrade Last Resort to a Z-Move, Extreme Evoboost.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (834, 'Mewnium Z', 'Hold items', 'Allows Mew to upgrade Psychic to a Z-Move, Genesis Supernova.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (836, 'Pikashunium Z', 'Hold items', 'Allows Pikachu in a cap to upgrade Thunderbolt to a Z-Move, 10,000,000 Volt Thunderbolt.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (841, 'Forage Bag', 'Key Items', 'A bag to carry ingredients gathered during Mallow''s trial in the jungle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (843, 'Professor''s Mask', 'Key Items', 'The mask that belongs to The Masked Royal. This pro wrestler apparently sews his mask on a machine himself.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (844, 'Festival Ticket', 'General items', 'A ticket that allows you to host a mission in Festival Plaza.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (845, 'Sparkling Stone', 'Key Items', 'A stone entrusted by a Pokémon that has been venerated as a guardian deity in the Alola region. There is said to be some secret in how it sparkles.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (846, 'Adrenaline Orb', 'Hold items', 'Using it makes wild Pokémon more likely to call for help. If held by a Pokémon, it boosts Speed when intimidated. It can be used only once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (847, 'Zygarde Cube', 'Key Items', 'An item to store Zygarde Cores and Cells. You can also use it to teach Zygarde moves.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (849, 'Ice Stone', 'General items', 'Evolves certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (850, 'Ride Pager', 'Key Items', 'By entering certain numbers on this pager, you can summon Ride Pokémon in an instant.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (851, 'Beast Ball', 'Pokeballs', 'A special Poké Ball designed to catch Ultra Beasts. It has a low success rate for catching others.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (852, 'Big Malasada', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (853, 'Red Nectar', 'Hold items', 'A flower nectar obtained at Ula''ula Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (854, 'Yellow Nectar', 'Hold items', 'A flower nectar obtained at Melemele Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (855, 'Pink Nectar', 'Hold items', 'The flower nectar obtained at the flowering shrubs on Royal Avenue. It changes the form of certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (856, 'Purple Nectar', 'Hold items', 'A flower nectar obtained at Poni Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (857, 'Sun Flute', 'Key Items', 'It is said that the tones it produces were offered up as an expression of gratitude to the Legendary Pokémon of the sun.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (858, 'Moon Flute', 'Key Items', 'It is said that the tones it produces were offered up as an expression of gratitude to the Legendary Pokémon of the moon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (860, 'Enigmatic Card', 'Key Items', 'A mysterious card. Written on it is a request for you to go to a guest room in an Akala motel on Route 8.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (861, 'Silver Razz Berry', 'Berries', 'Makes a Pokémon easier to catch in Pokémon Let''s Go.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (862, 'Golden Razz Berry', 'Berries', 'Makes a Pokémon easier to catch in Pokémon Let''s Go.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (863, 'Silver Nanab Berry', 'Berries', 'Greatly calms a Pokémon in battle, in Let''s Go Pikachu/Eevee.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (864, 'Golden Nanab Berry', 'Berries', 'Drastically calms a Pokémon in battle, in Let''s Go Pikachu/Eevee.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (865, 'Silver Pinap Berry', 'Berries', 'Greatly increases chance of getting items when a Pokémon is caught, in Pokémon Let''s Go.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (866, 'Golden Pinap Berry', 'Berries', 'Drastically increases chance of getting items when a Pokémon is caught, in Pokémon Let''s Go.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (872, 'Secret Key', 'Key Items', 'A high-tech key that has to be used at a specific location. It emits a special electric signal to open a door.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (873, 'S.S. Ticket', 'Key Items', 'The ticket required for sailing on the ferry S.S. Aqua. It has a drawing of a ship on it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (874, 'Silph Scope', 'Key Items', 'A scope that makes unseeable POKéMON visible. It is made by SILPH CO.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (875, 'Parcel', 'Key Items', 'A parcel entrusted in your care. You are supposed to deliver it to your childhood friend who left Twinleaf Town.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (876, 'Card Key', 'Key Items', 'A card key that opens a shutter in the Radio Tower.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (877, 'Gold Teeth', 'Key Items', 'A set of false teeth lost by the SAFARI ZONE''S WARDEN. It makes his smile sparkle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (878, 'Lift Key', 'Key Items', 'A key that operates the elevator in TEAM ROCKET''s HIDEOUT. It bears the TEAM ROCKET logo.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (879, 'Terrain Extender', 'Hold items', 'An item to be held by a Pokémon. It extends the duration of the terrain caused by the holder''s move or Ability.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (880, 'Protective Pads', 'Hold items', 'An item to be held by a Pokémon. These pads protect the holder from effects caused by making direct contact with the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (881, 'Electric Seed', 'Hold items', 'An item to be held by a Pokémon. It boosts Defense on Electric Terrain. It can only be used once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (882, 'Psychic Seed', 'Hold items', 'An item to be held by a Pokémon. It boosts Sp. Def on Psychic Terrain. It can only be used once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (883, 'Misty Seed', 'Hold items', 'An item to be held by a Pokémon. It boosts Sp. Def on Misty Terrain. It can only be used once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (884, 'Grassy Seed', 'Hold items', 'An item to be held by a Pokémon. It boosts Defense on Grassy Terrain. It can only be used once.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (885, 'Stretchy Spring', 'General items', 'A thin small spring. It’s totally stretched out, and what it’s used for is unknown.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (886, 'Chalky Stone', 'General items', 'A small whitish stone picked up at the edge of the road.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (887, 'Marble', 'General items', 'A round glass marble. You can see colored glass inside the transparent marble.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (888, 'Lone Earring', 'General items', 'A single earring that somebody dropped.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (889, 'Beach Glass', 'General items', 'A piece of colored glass. Waves have rounded its edges. It''s slightly rough to the touch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (890, 'Gold Leaf', 'General items', 'A mysterious gold leaf. No trees with this leaf have been found yet.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (891, 'Silver Leaf', 'General items', 'A mysterious silver leaf. No trees with this leaf have been found yet.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (892, 'Polished Mud Ball', 'General items', 'A ball made of mud. It had been polished for such a long time that the surface is very shiny.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (893, 'Tropical Shell', 'General items', 'A beautiful white shell that may have drifted from a sea in a warm region.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (895, 'Leaf Letter', 'General items', 'A letter written on a leaf. Something is written using Eevee''s footprints.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (896, 'Small Bouquet', 'General items', 'A small bouquet that was made with heart and soul for a single Trainer.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (900, 'Lure', 'General items', 'Attracts Pokémon in the wild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (901, 'Super Lure', 'General items', 'Attracts Pokémon in the wild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (902, 'Max Lure', 'General items', 'Attracts Pokémon in the wild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (903, 'Pewter Crunchies', 'Medicine', 'Heals all major status conditions.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (904, 'Fighting Memory', 'Hold items', 'Changes Silvally and its move Multi-Attack to Fighting type.');
