INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (927, 'Solganium Z', 'Hold items', 'Allows Solgaleo to upgrade Sunsteel Strike to a Z-Move, Searing Sunraze Smash.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (928, 'Lunalium Z', 'Hold items', 'Allows Lunala to upgrade Moongeist Beam to a Z-Move, Menacing Moonraze Maelstrom.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (929, 'Ultranecrozium Z', 'Hold items', 'Allows Ultra Necrozma to upgrade Photon Geyser to a Z-Move, Light That Burns the Sky.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (930, 'Mimikium Z', 'Hold items', 'Allows Mimikyu to upgrade Play Rough to a Z-Move, Let''s Snuggle Forever.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (931, 'Lycanium Z', 'Hold items', 'Allows Lycanroc to upgrade Stone Edge to a Z-Move, Splintered Stormshards.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (932, 'Kommonium Z', 'Hold items', 'Allows Kommo-o to upgrade Clanging Scales to a Z-Move, Clangorous Soulblaze.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (934, 'Pink Petal', 'Key Items', 'Petal received from Mina during Mina''s trial.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (935, 'Orange Petal', 'Key Items', 'Petal received from Ilima during Mina''s trial.');
