INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (941, 'Rainbow Flower', 'Key Items', 'Flower made of the petals received from captains.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (942, 'Surge Badge', 'Key Items', 'Novelty badge from the Kantonian Gym.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (945, 'N-Solarizer', 'Key Items', 'A machine to fuse/separate Necrozma and Solgaleo.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (946, 'N-Lunarizer', 'Key Items', ' A machine to fuse/separate Necrozma and Lunala.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (948, 'Left Poké Ball', 'Key Items', 'A Poké Ball with a Pokémon that lost its Trainer inside.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (949, 'Roto Hatch', 'Battle items', 'Helps Eggs hatch faster.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (950, 'Roto Bargain', 'Battle items', 'Reduces the prices of products at Poké Marts by half.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (951, 'Roto Prize Money', 'Battle items', 'Triples the prize money you receive after battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (952, 'Roto Exp. Points', 'Battle items', 'Increases the Exp. Points your Pokémon receive after battle a little.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (953, 'Roto Friendship', 'Battle items', 'Helps Pokémon in your party grow friendly faster.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (954, 'Roto Encounter', 'Battle items', 'Increases the chance of encountering high-level wild Pokémon a lot for a certain period of time.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (955, 'Roto Stealth', 'Battle items', 'Prevents you from encountering wild Pokémon for a certain period of time.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (956, 'Roto HP Restore', 'Battle items', 'Fully restores the HP of your battling Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (957, 'Roto PP Restore', 'Battle items', 'Fully restores the PP of your battling Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (958, 'Roto Boost', 'Battle items', 'Raises all stats of your battling Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (959, 'Roto Catch', 'Battle items', 'Increases the chance to catch Pokémon a lot.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (960, 'Health Candy', 'Medicine', 'Increases a Pokémon''s HP stat by 1.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (961, 'Mighty Candy', 'Medicine', 'Increases a Pokémon''s Attack stat by 1.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (962, 'Tough Candy', 'Medicine', 'Increases a Pokémon''s Defense stat by 1.');
