INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (977, 'Quick Candy XL', 'Medicine', 'Increases a Pokémon''s Speed stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1075, 'Pokémon Box Link', 'Key Items', 'A device that allows you to access the Pokémon storage system. There are some places where it won’t work.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1076, 'Wishing Star', 'Key Items', 'A stone found in the Galar region with a mysterious power. It’s said that your dreams come true if you find one.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1077, 'Dynamax Band', 'Key Items', 'A Wishing Star has been affixed to it. It lets out a light that allows Pokémon to Dynamax when at a Power Spot.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1080, 'Fishing Rod', 'Key Items', 'A Fishing Rod made by Captain Lana. Cast a line over piles of underwater rocks to fish for wild aquatic Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1084, 'Sausages', 'General items', 'One of the many ingredients that can be used for cooking at your camp. These sausages should be boiled before eating.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1085, 'Bob''s Food Tin', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bob sells is curiously popular in Galar.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1086, 'Bach''s Food Tin', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bach sells is curiously popular in Galar.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1087, 'Tin of Beans', 'General items', 'One of the many ingredients that can be used for cooking at your camp. When simmered, the beans suffuse a dish with their mild flavor.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1088, 'Bread', 'General items', 'One of the many ingredients that can be used for cooking at your camp. An indispensable tool for mopping up that extra curry left on your plate.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1089, 'Pasta', 'General items', 'One of the many ingredients that can be used for cooking at your camp. These flour noodles make for a surprisingly good match with curry.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1090, 'Mixed Mushrooms', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The chewy texture of the mushrooms transforms any dish they’re added to.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1091, 'Smoke-Poke Tail', 'General items', 'One of the many ingredients that can be used for cooking at your camp. When a Slowpoke’s tail falls off, it grows back quickly.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1092, 'Large Leek', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Whether this is the kind of vegetable stalk that Farfetch’d like is unknown.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1093, 'Fancy Apple', 'General items', 'One of the many ingredients that can be used for cooking at your camp. An apple chosen above others. It has spectacular form and a brilliant sheen.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1094, 'Brittle Bones', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The taste boiled off from the bones is sure to give a dish a light umami taste.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1095, 'Pack of Potatoes', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Potatoes help mellow out a spicy taste, to make a dish more mild.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1096, 'Pungent Root', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Though carelessly picked, these herbs can add a fragrant accent to a dish.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1097, 'Salad Mix', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The assortment of vegetables looks quite appealing and healthy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1098, 'Fried Food', 'General items', 'One of the many ingredients that can be used for cooking at your camp. It’s been a while since it was fried, so it’s gotten greasy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1099, 'Boiled Egg', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Even just one boiled egg can really enhance a dish.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1100, 'Camping Gear', 'Key Items', 'Everything you need to set up a tent and get cooking in a Wild Area or at a camping spot.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1103, 'Rusted Sword', 'Key Items', 'It is said that a hero used this sword to halt a terrible disaster in ancient times. But it’s grown rusty and worn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1104, 'Rusted Shield', 'Key Items', 'It is said that a hero used this shield to halt a terrible disaster in ancient times. But it’s grown rusty and worn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1105, 'Fossilized Bird', 'General items', 'The fossil of an ancient Pokémon that once soared through the sky. What it looked like is a mystery.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1106, 'Fossilized Fish', 'General items', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1107, 'Fossilized Drake', 'General items', 'The fossil of an ancient Pokémon that once roamed the land. What it looked like is a mystery.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1108, 'Fossilized Dino', 'General items', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1109, 'Strawberry Sweet', 'Hold items', 'Evolves Milcery into Strawberry Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1110, 'Love Sweet', 'Hold items', 'Evolves Milcery into Heart Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1111, 'Berry Sweet', 'Hold items', 'Evolves Milcery into Blueberry Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1112, 'Clover Sweet', 'Hold items', 'Evolves Milcery into Clover Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1113, 'Flower Sweet', 'Hold items', 'Evolves Milcery into Flower Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1114, 'Star Sweet', 'Hold items', 'Evolves Milcery into Star Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1115, 'Ribbon Sweet', 'Hold items', 'Evolves Milcery into Ribbon Flavor Alcremie.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1116, 'Sweet Apple', 'Hold items', 'Evolves Applin into Appletun.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1117, 'Tart Apple', 'Hold items', 'Evolves Applin into Flapple.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1118, 'Throat Spray', 'Hold items', 'Raises Sp. Atk when a sound-based move is used.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1119, 'Eject Pack', 'Hold items', 'The Pokémon switches out if its stats are lowered.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1120, 'Heavy-Duty Boots', 'Hold items', 'Protects the holder from traps set on the battlefield.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1121, 'Blunder Policy', 'Hold items', 'Raises Speed sharply if its attack misses.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1122, 'Room Service', 'Hold items', 'Lowers the Pokémon''s speed during Trick Room.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1123, 'Utility Umbrella', 'Hold items', 'An item to be held by a Pokémon. This sturdy umbrella protects the holder from the effects of weather.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1124, 'Exp. Candy XS', 'Medicine', 'A candy that is packed with energy. If consumed, it grants a Pokémon a very small number of Exp. Points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1125, 'Exp. Candy S', 'Medicine', 'A candy that is packed with energy. If consumed, it grants a Pokémon a small number of Exp. Points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1126, 'Exp. Candy M', 'Medicine', 'A candy that is packed with energy. If consumed, it grants a Pokémon a moderate number of Exp. Points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1127, 'Exp. Candy L', 'Medicine', 'A candy that is packed with energy. If consumed, it grants a Pokémon a large number of Exp. Points.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1128, 'Exp. Candy XL', 'Medicine', 'Increases the Pokémon''s Exp points by 30,000.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1129, 'Dynamax Candy', 'Medicine', 'Raises Dynamax Level.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1130, 'TR00', 'Machines', 'Teaches the move Swords Dance.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1131, 'TR01', 'Machines', 'The user drops onto the target with its full body weight. This may also leave the target with paralysis.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1132, 'TR02', 'Machines', 'The target is scorched with an intense blast of fire. This may also leave the target with a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1133, 'TR03', 'Machines', 'The target is blasted by a huge volume of water launched under great pressure.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1134, 'TR04', 'Machines', 'The user attacks everything around it by swamping its surroundings with a giant wave.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1135, 'TR05', 'Machines', 'The target is struck with an icy-cold beam of energy. This may also leave the target frozen.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1136, 'TR06', 'Machines', 'A howling blizzard is summoned to strike opposing Pokémon. This may also leave the opposing Pokémon frozen.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1137, 'TR07', 'Machines', 'A powerful low kick that makes the target fall over. The heavier the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1138, 'TR08', 'Machines', 'A strong electric blast crashes down on the target. This may also leave the target with paralysis.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1139, 'TR09', 'Machines', 'A wicked thunderbolt is dropped on the target to inflict damage. This may also leave the target with paralysis.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1140, 'TR10', 'Machines', 'The user sets off an earthquake that strikes every Pokémon around it.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1141, 'TR11', 'Machines', 'The target is hit by a strong telekinetic force. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1142, 'TR12', 'Machines', 'The user relaxes and lightens its body to move faster. This sharply raises the Speed stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1143, 'TR13', 'Machines', 'The user takes a deep breath and focuses so that critical hits land more easily.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1144, 'TR14', 'Machines', 'The user waggles a finger and stimulates its brain into randomly using nearly any move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1145, 'TR15', 'Machines', 'The target is attacked with an intense blast of all-consuming fire. This may also leave the target with a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1146, 'TR16', 'Machines', 'The user charges at the target and may make it flinch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1147, 'TR17', 'Machines', 'The user temporarily empties its mind to forget its concerns. This sharply raises the user’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1148, 'TR18', 'Machines', 'The user drains the target’s blood. The user’s HP is restored by half the damage taken by the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1149, 'TR19', 'Machines', 'The user strikes with a simultaneous three-beam attack. This may also burn, freeze, or paralyze the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1150, 'TR20', 'Machines', 'The user creates a substitute for itself using some of its own HP. The substitute serves as the user’s decoy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1151, 'TR21', 'Machines', 'An all-out attack that becomes more powerful the less HP the user has.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1152, 'TR22', 'Machines', 'Unsanitary sludge is hurled at the target. This may also poison the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1153, 'TR23', 'Machines', 'The user lays a trap of spikes at the opposing team’s feet. The trap hurts Pokémon that switch into battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1154, 'TR24', 'Machines', 'The user rampages and attacks for two to three turns. The user then becomes confused.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1155, 'TR25', 'Machines', 'The user materializes an odd psychic wave to attack the target. This attack does physical damage.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1156, 'TR26', 'Machines', 'The user endures any attack with at least 1 HP. Its chance of failing rises if it is used in succession.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1157, 'TR27', 'Machines', 'While it is asleep, the user randomly uses one of the moves it knows.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1158, 'TR28', 'Machines', 'Using its tough and impressive horn, the user rams into the target with no letup.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1159, 'TR29', 'Machines', 'The user switches places with a party Pokémon in waiting and passes along any stat changes.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1160, 'TR30', 'Machines', 'The user compels the target to keep using the move it encored for three turns.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1161, 'TR31', 'Machines', 'The target is slammed with a steel-hard tail. This may also lower the target’s Defense stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1162, 'TR32', 'Machines', 'The user crunches up the target with sharp fangs. This may also lower the target’s Defense stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1163, 'TR33', 'Machines', 'The user hurls a shadowy blob at the target. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1164, 'TR34', 'Machines', 'Two turns after this move is used, a hunk of psychic energy attacks the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1165, 'TR35', 'Machines', 'The user attacks in an uproar for three turns. During that time, no Pokémon can fall asleep.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1166, 'TR36', 'Machines', 'The user attacks by exhaling hot breath on opposing Pokémon. This may also leave those Pokémon with a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1167, 'TR37', 'Machines', 'The target is taunted into a rage that allows it to use only attack moves for three turns.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1168, 'TR38', 'Machines', 'The user catches the target off guard and swaps its held item with its own.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1169, 'TR39', 'Machines', 'The user attacks the target with great power. However, this also lowers the user’s Attack and Defense stats.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1170, 'TR40', 'Machines', 'The user employs its psychic power to exchange Abilities with the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1171, 'TR41', 'Machines', 'The user launches a kick that lands a critical hit more easily. This may also leave the target with a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1172, 'TR42', 'Machines', 'The user lets loose a horribly echoing shout with the power to inflict damage.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1173, 'TR43', 'Machines', 'The user attacks the target at full power. The attack’s recoil harshly lowers the user’s Sp. Atk stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1174, 'TR44', 'Machines', 'The user absorbs a mystical power from space to raise its Defense and Sp. Def stats.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1175, 'TR45', 'Machines', 'The user attacks by shooting muddy water at opposing Pokémon. This may also lower their accuracy.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1176, 'TR46', 'Machines', 'The user hardens its body’s surface like iron, sharply raising its Defense stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1177, 'TR47', 'Machines', 'The user slashes the target with huge sharp claws.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1178, 'TR48', 'Machines', 'The user tenses its muscles to bulk up its body, raising both its Attack and Defense stats.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1179, 'TR49', 'Machines', 'The user quietly focuses its mind and calms its spirit to raise its Sp. Atk and Sp. Def stats.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1180, 'TR50', 'Machines', 'The user handles a sharp leaf like a sword and attacks by cutting its target. Critical hits land more easily.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1181, 'TR51', 'Machines', 'Teaches the move Dragon Dance.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1182, 'TR52', 'Machines', 'The user tackles the target with a high-speed spin. The slower the user compared to the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1183, 'TR53', 'Machines', 'The user fights the target up close without guarding itself. This also lowers the user’s Defense and Sp. Def stats.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1184, 'TR54', 'Machines', 'The user lays a trap of poison spikes at the feet of the opposing team. The spikes will poison opposing Pokémon that switch into battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1185, 'TR55', 'Machines', 'The user cloaks itself in fire and charges the target. This also damages the user quite a lot. This attack may leave the target with a burn.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1186, 'TR56', 'Machines', 'The user lets loose a blast of aura power from deep within its body at the target. This attack never misses.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1187, 'TR57', 'Machines', 'The target is stabbed with a tentacle, arm, or the like steeped in poison. This may also poison the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1188, 'TR58', 'Machines', 'The user releases a horrible aura imbued with dark thoughts. This may also make the target flinch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1189, 'TR59', 'Machines', 'The user slams a barrage of hard-shelled seeds down on the target from above.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1190, 'TR60', 'Machines', 'The user slashes at the target by crossing its scythes or claws as if they were a pair of scissors.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1191, 'TR61', 'Machines', 'The user generates a damaging sound wave by vibration. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1192, 'TR62', 'Machines', 'The target is attacked with a shock wave generated by the user’s gaping mouth.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1193, 'TR63', 'Machines', 'The user attacks with a ray of light that sparkles as if it were made of gemstones.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1194, 'TR64', 'Machines', 'The user heightens its mental focus and unleashes its power. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1195, 'TR65', 'Machines', 'The user draws power from nature and fires it at the target. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1196, 'TR66', 'Machines', 'The user tucks in its wings and charges from a low altitude. This also damages the user quite a lot.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1197, 'TR67', 'Machines', 'The user makes the ground under the target erupt with power. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1198, 'TR68', 'Machines', 'The user stimulates its brain by thinking bad thoughts. This sharply raises the user’s Sp. Atk stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1199, 'TR69', 'Machines', 'The user focuses its willpower to its head and attacks the target. This may also make the target flinch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1200, 'TR70', 'Machines', 'The user gathers all its light energy and releases it all at once. This may also lower the target’s Sp. Def stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1201, 'TR71', 'Machines', 'The user whips up a storm of leaves around the target. The attack’s recoil harshly lowers the user’s Sp. Atk stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1202, 'TR72', 'Machines', 'The user violently whirls its vines, tentacles, or the like to harshly lash the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1203, 'TR73', 'Machines', 'The user shoots filthy garbage at the target to attack. This may also poison the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1204, 'TR74', 'Machines', 'The user slams the target with its steel-hard head. This may also make the target flinch.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1205, 'TR75', 'Machines', 'The user stabs the target from below with sharpened stones. Critical hits land more easily.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1206, 'TR76', 'Machines', 'The user lays a trap of levitating stones around the opposing team. The trap hurts opposing Pokémon that switch into battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1207, 'TR77', 'Machines', 'The user snares the target with grass and trips it. The heavier the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1208, 'TR78', 'Machines', 'The user strikes everything around it by swamping the area with a giant sludge wave. This may also poison those hit.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1209, 'TR79', 'Machines', 'The user slams into the target with its heavy body. The more the user outweighs the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1210, 'TR80', 'Machines', 'The user hurls an electric orb at the target. The faster the user is than the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1211, 'TR81', 'Machines', 'Teaches the move Foul Play.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1212, 'TR82', 'Machines', 'The user attacks the target with stored power. The more the user’s stats are raised, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1213, 'TR83', 'Machines', 'The user teleports using a strange power and switches places with one of its allies.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1214, 'TR84', 'Machines', 'Teaches the move Scald.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1215, 'TR85', 'Machines', 'The user is roused, and its Attack and Sp. Atk stats increase.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1216, 'TR86', 'Machines', 'The user shrouds itself in electricity and smashes into its target. This also damages the user a little.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1217, 'TR87', 'Machines', 'The user crashes into its target while rotating its body like a drill. Critical hits land more easily.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1218, 'TR88', 'Machines', 'The user slams its target with its flame-covered body. The more the user outweighs the target, the greater the move’s power.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1219, 'TR89', 'Machines', 'The user attacks by wrapping its opponent in a fierce wind that flies up into the sky. This may also confuse the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1220, 'TR90', 'Machines', 'The user plays rough with the target and attacks it. This may also lower the target’s Attack stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1221, 'TR91', 'Machines', 'Opposing Pokémon are drenched in an odd poisonous liquid. This lowers the Attack, Sp. Atk, and Speed stats of a poisoned target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1222, 'TR92', 'Machines', 'The user damages opposing Pokémon by emitting a powerful flash.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1223, 'TR93', 'Machines', 'The user swings both arms and hits the target. The target’s stat changes don’t affect this attack’s damage.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1224, 'TR94', 'Machines', 'The user fiercely attacks the target using its entire body.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1225, 'TR95', 'Machines', 'The user attacks the target’s throat, and the resultant suffering prevents the target from using moves that emit sound for two turns.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1227, 'TR97', 'Machines', 'The user bites the target with its psychic capabilities. This can also destroy Light Screen and Reflect.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1228, 'TR98', 'Machines', 'The user slams into the target using a full-force blast of water. This may also lower the target’s Defense stat.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1229, 'TR99', 'Machines', 'The user attacks by slamming its body into the target. The higher the user’s Defense, the more damage it can inflict on the target.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1230, 'TM00', 'Machines', 'Teaches a move.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1231, 'Lonely Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Lonely nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1232, 'Adamant Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Adamant nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1233, 'Naughty Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Naughty nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1234, 'Brave Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Brave nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1235, 'Bold Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Bold nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1236, 'Impish Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Impish nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1237, 'Lax Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Lax nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1238, 'Relaxed Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Relaxed nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1239, 'Modest Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Modest nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1240, 'Mild Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Mild nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1241, 'Rash Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Rash nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1242, 'Quiet Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Quiet nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1243, 'Calm Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Calm nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1244, 'Gentle Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Gentle nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1245, 'Careful Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Careful nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1246, 'Sassy Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Sassy nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1247, 'Timid Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Timid nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1248, 'Hasty Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Hasty nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1249, 'Jolly Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Jolly nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1250, 'Naive Mint', 'Battle items', 'Changes the Pokémon''s stats to match the Naive nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1251, 'Serious Mint', 'Battle items', 'Changes the Pokémon''s stats to match a neutral nature.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1252, 'Wishing Piece', 'General items', 'Activates a Pokémon Den for a Max Raid Battle.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1253, 'Cracked Pot', 'Hold items', 'Evolves Sinistea into Polteageist.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1254, 'Chipped Pot', 'Hold items', 'Evolves Sinistea into Polteageist.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1255, 'Hi-tech Earbuds', 'Hold items', 'Strange earbuds that allow you to freely control the volume of various sounds.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1256, 'Fruit Bunch', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The syrupy fruits give off a strong tropical feel.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1257, 'Moomoo Cheese', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Melted cheese can really give a curry some richness.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1258, 'Spice Mix', 'General items', 'One of the many ingredients that can be used for cooking at your camp. There are over fifty spices contained within this ingredient’s hot flavor.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1259, 'Fresh Cream', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Add some whipped cream to a spicy curry to give it some sweetness.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1260, 'Packaged Curry', 'General items', 'One of the many ingredients that can be used for cooking at your camp. Using packaged curry helps make sure there are no slipups when cooking.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1261, 'Coconut Milk', 'General items', 'One of the many ingredients that can be used for cooking at your camp. The refined sweetness of this coconut milk makes it quite popular.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1262, 'Instant Noodles', 'General items', 'One of the many ingredients that can be used for cooking at your camp. It has a junk-food sort of taste, but it goes well with curry.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1263, 'Precooked Burger', 'General items', 'One of the many ingredients that can be used for cooking at your camp. If you’re unsure about what to cook, you can’t go wrong with some burger.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1264, 'Gigantamix', 'General items', 'One of the many ingredients that can be used for cooking at your camp. A mysterious spice. Even a tiny sprinkle is sure to make a curry gigantic.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1265, 'Wishing Chip', 'Key Items', 'Toss a number of them into a Pokémon Den for the chance to attract a wild Dynamax Pokémon.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1266, 'Rotom Bike', 'Key Items', 'This bike can be combined with the Pokémon Rotom to not only do a turbo boost but also run on the water.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1267, 'Catching Charm', 'Key Items', 'Holding it is said to increase the chance of getting a critical catch. Curiously, the charm doesn’t shake much.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1269, 'Old Letter', 'Key Items', 'A letter entrusted to you by a girl, to be delivered to a boy. Strangely, it looks old to you.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1270, 'Band Autograph', 'Key Items', 'It’s signed by all members of the Galar region’s most charismatic band, the Maximizers.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1271, 'Sonia''s Book', 'Key Items', 'Professor Sonia’s published writings. Her new discoveries about the Galar region’s legends are recorded in this enjoyable read.');
INSERT INTO POKEMON_ITEMS (ITEM_ID, ITEM_NAME, CATEGORY, EFFECT) VALUES (1278, 'Rotom Catalog', 'Key Items', 'A catalog of devices that Rotom like. Use the catalog to have Rotom hop in and out of the various devices listed within.');
