CREATE TABLE POKEMON_ITEMS (
    ITEM_ID         NUMBER CONSTRAINT pk_item PRIMARY KEY,
    ITEM_NAME       VARCHAR2(200) NOT NULL UNIQUE,
    CATEGORY        VARCHAR2(100),
    EFFECT          VARCHAR2(1000)
);

