-- ======================================================================
-- VERIFICATION QUERIES
-- ======================================================================

-- Total count
SELECT COUNT(*) AS TOTAL_ITEMS FROM POKEMON_ITEMS;

-- Items by category
SELECT 
    NVL(CATEGORY, 'Uncategorized') AS CATEGORY,
    COUNT(*) AS ITEM_COUNT
FROM POKEMON_ITEMS
GROUP BY CATEGORY
ORDER BY ITEM_COUNT DESC;

-- Sample data
SELECT * FROM POKEMON_ITEMS WHERE ROWNUM <= 30 ORDER BY ITEM_ID;

